record.field:
for record in records:
    # Check that category code is unique if provided
    if not record.x_studio_category_code:
        continue

    duplicate = env['x_service_category'].search([
        ('x_studio_category_code', '=', record.x_studio_category_code),
        ('id', '!=', record.id),
    ], limit=1)

    if duplicate:
        raise UserError(
            "Category Code '%s' already exists. Please use a unique Category Code."
            % record.x_studio_category_code
        )

for record in records:
    # Check that service code is unique if provided
    if not record.x_studio_service_code:
        continue

    duplicate = env['x_service'].search([
        ('x_studio_service_code', '=', record.x_studio_service_code),
        ('id', '!=', record.id),
    ], limit=1)

    if duplicate:
        raise UserError(
            "Service Code '%s' already exists. Please enter a unique Service Code."
            % record.x_studio_service_code
        )

for record in records:
    # Check that package code is unique if provided
    if not record.x_studio_package_code:
        continue

    duplicate = env['x_service_package'].search([
        ('x_studio_package_code', '=', record.x_studio_package_code),
        ('id', '!=', record.id),
    ], limit=1)

    if duplicate:
        raise UserError(
            "Package Code '%s' already exists. "
            "Please enter a unique Package Code."
            % record.x_studio_package_code
        )

for record in records:
    # Ensure package discount percentage is between 0 and 100
    if record.x_studio_discount_1 < 0 or record.x_studio_discount_1 > 100:
        raise UserError(
            "Discount must be between 0 and 100."
        )

for record in records:
    # Calculate and cache original total price based on included services
    total = 0.0

    for service in record.x_studio_many2many_1:
        total += service.x_studio_value

    record.write({
        'x_studio_original_value': total,
    })

for record in records:
    # Calculate package final value by subtracting the discount from original total value
    original_value = record.x_studio_original_value or 0.0
    discount = record.x_studio_discount_1 or 0

    package_price = original_value - (
        original_value * discount / 100
    )

    record.write({
        'x_studio_value': package_price,
    })

for record in records:
    # Server action to create a customer invoice dynamically from appointment data

    # Validate customer
    if not record.x_studio_partner_id:
        raise UserError("Please select a Customer.")

    # Validate service / package based on booking type
    if record.x_studio_booking_type == 'service':
        if not record.x_studio_service:
            raise UserError("Please select a Service.")
        line_name = record.x_studio_service.x_name
    elif record.x_studio_booking_type == 'package':
        if not record.x_studio_service_package:
            raise UserError("Please select a Service Package.")
        line_name = record.x_studio_service_package.x_name
    else:
        raise UserError("Please select a Booking Type.")

    # Prevent duplicate invoice
    if record.x_studio_invoice_1:
        raise UserError(
            "An invoice has already been created for this appointment."
        )

    # Create invoice
    invoice = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': record.x_studio_partner_id.id,
        'invoice_date': datetime.date.today(),
        'x_studio_appointment_id': record.id,
        'invoice_line_ids': [(0, 0, {
            'name': line_name,
            'quantity': 1,
            'price_unit': record.x_studio_value or 0.0,
        })],
    })

    # Link invoice to appointment
    record.write({
        'x_studio_invoice_1': invoice.id,
    })

for record in records:
    # Check if this is a website guest booking request (which writes to x_studio_text_1)
    if record.x_studio_text_1:
        partner = False
        # Search for existing partner by email
        if record.x_studio_partner_email:
            partner = env['res.partner'].sudo().search([('email', '=', record.x_studio_partner_email)], limit=1)
        # Create partner if not found
        if not partner:
            partner = env['res.partner'].sudo().create({
                'name': record.x_studio_text_1,
                'email': record.x_studio_partner_email or False,
                'phone': record.x_studio_partner_phone or False,
            })
        # Set partner on the appointment
        if record.x_studio_partner_id != partner:
            record.sudo().write({'x_studio_partner_id': partner.id})

    vals = {}
    # Generate unique sequence code if none is set
    if not record.x_name or record.x_name == 'New':
        vals['x_name'] = env['ir.sequence'].sudo().next_by_code('salon.appointment') or 'New'

    price = 0.0
    duration = 0

    # Auto populate price and duration based on selected service or package
    if record.x_studio_booking_type == 'service' and record.x_studio_service:
        price = record.x_studio_service.sudo().x_studio_value or 0.0
        duration = record.x_studio_service.sudo().x_studio_duration_minutes or 0
    elif record.x_studio_booking_type == 'package' and record.x_studio_service_package:
        price = record.x_studio_service_package.sudo().x_studio_value or 0.0
        if record.x_studio_service_package.sudo().x_studio_many2many_1:
            duration = sum(s.x_studio_duration_minutes or 0 for s in record.x_studio_service_package.sudo().x_studio_many2many_1)

    if record.x_studio_value != price:
        vals['x_studio_value'] = price
    if record.x_studio_duration != duration:
        vals['x_studio_duration'] = duration

    if vals:
        record.sudo().write(vals)

# Ensure appointment sequence has BKG/ prefix
seq = env.ref('salon_management_saas.seq_salon_appointment', raise_if_not_found=False)
if seq and seq.prefix != 'BKG/':
    seq.sudo().write({'prefix': 'BKG/'})

for record in records:
    # Compute UTC start and end datetimes based on local timezone and selected slot
    if record.x_studio_date and record.x_studio_time_slot:
        user_tz = env.context.get('tz') or env.user.tz or 'UTC'
        local_tz = timezone(user_tz)
        hour, minute = map(int, record.x_studio_time_slot.split(':'))
        naive_start = datetime.datetime.combine(record.x_studio_date, datetime.time(hour, minute))
        try:
            local_start = local_tz.localize(naive_start)
        except Exception:
            local_start = naive_start.replace(tzinfo=local_tz)
        utc_start = local_start.astimezone(timezone('UTC')).replace(tzinfo=None)

        duration_mins = record.x_studio_duration or 30
        utc_end = utc_start + datetime.timedelta(minutes=duration_mins)

        vals = {}
        if record.x_studio_start_time != utc_start:
            vals['x_studio_start_time'] = utc_start
        if record.x_studio_end_time != utc_end:
            vals['x_studio_end_time'] = utc_end
        if vals:
            record.sudo().write(vals)
    elif record.x_studio_start_time and record.x_studio_duration:
        duration_mins = record.x_studio_duration
        end_time = record.x_studio_start_time + datetime.timedelta(minutes=duration_mins)
        if record.x_studio_end_time != end_time:
            record.sudo().write({'x_studio_end_time': end_time})

for record in records:
    if not record.x_studio_date:
        raise UserError("Appointment Date is not set.")
    if record.x_studio_date < datetime.date.today():
        raise UserError("Conflict: You cannot confirm an appointment for a past date (%s)." % record.x_studio_date)

    record.write({'x_studio_selection_1': 'Confirmed'})

    note_subtype_id = env.ref('mail.mt_note').id

    # Send email to Customer and log in chatter
    template_cust = env.ref('salon_management_saas.mail_template_appointment_confirm_customer', raise_if_not_found=False)
    if template_cust and record.x_studio_partner_email:
        mail_id = False
        try:
            mail_id = template_cust.send_mail(record.id, force_send=True)
        except Exception:
            mail_id = template_cust.send_mail(record.id, force_send=False)
        if mail_id:
            mail = env['mail.mail'].browse(mail_id).exists()
            if mail and mail.mail_message_id:
                mail.mail_message_id.write({'subtype_id': note_subtype_id})

    # Send email to Staff and log in chatter
    template_staff = env.ref('salon_management_saas.mail_template_appointment_confirm_staff', raise_if_not_found=False)
    if template_staff and record.x_studio_staff_beautician and record.x_studio_staff_beautician.work_email:
        mail_id = False
        try:
            mail_id = template_staff.send_mail(record.id, force_send=True)
        except Exception:
            mail_id = template_staff.send_mail(record.id, force_send=False)
        if mail_id:
            mail = env['mail.mail'].browse(mail_id).exists()
            if mail and mail.mail_message_id:
                mail.mail_message_id.write({'subtype_id': note_subtype_id})

for record in records:
    current_date = datetime.date.today()
    if not record.x_studio_date:
        raise UserError("Appointment Date is not set.")
    if record.x_studio_date != current_date:
        raise UserError(
            "Conflict: You can only start the service on the scheduled appointment date (%s)."
            % record.x_studio_date
        )

    now = datetime.datetime.now()
    duration = record.x_studio_duration or 0
    end_time = now + datetime.timedelta(minutes=duration)

    record.write({
        'x_studio_selection_1': 'In Progress',
        'x_studio_start_time': now,
        'x_studio_end_time': end_time,
    })

packages = env['x_service_package'].search([
    ('x_studio_status', '=', 'active'),
    ('x_studio_limited_time', '=', True),
    ('x_studio_end_date', '!=', False),
])
for package in packages:
    if datetime.date.today() >= package.x_studio_end_date:
        package.write({'x_studio_status': 'inactive'})

for record in records:
    if record.x_studio_status == 'inactive' and record.x_active:
        record.write({'x_active': False})

# Collect all chairs that need to be updated
chairs_to_update = env['x_chair'].sudo()

for record in records:
    if record.x_studio_chair_num:
        chairs_to_update |= record.x_studio_chair_num.sudo()

# Also search for active ones to keep it simple and correct.
all_chairs = env['x_chair'].sudo().search([])
for chair in all_chairs:
    # Search all corresponding confirmed appointments for this chair
    all_appointments = env['x_appointment'].sudo().search([
        ('x_studio_chair_num', '=', chair.id),
        ('x_studio_selection_1', '=', 'Confirmed')
    ])

    if chair.x_studio_filter_date:
        bookings_to_show = all_appointments.filtered(
            lambda a: a.x_studio_date == chair.x_studio_filter_date
        )
    else:
        bookings_to_show = all_appointments

    vals = {
        'x_studio_bookings': [(6, 0, bookings_to_show.ids)],
    }
    if not chair.x_studio_filter_date:
        vals['x_studio_filter_date'] = datetime.date.today()

    chair.sudo().with_context(onchange_self=None).write(vals)

for record in records:
    if record.x_studio_filter_date:
        appointments = env['x_appointment'].search([
            ('x_studio_chair_num', '=', record.id),
            ('x_studio_date', '=', record.x_studio_filter_date),
            ('x_studio_selection_1', '=', 'Confirmed')
        ])
    else:
        appointments = env['x_appointment'].search([
            ('x_studio_chair_num', '=', record.id),
            ('x_studio_selection_1', '=', 'Confirmed')
        ])

    record.write({
        'x_studio_bookings': [(6, 0, appointments.ids)]
    })

for record in records:
    if record.x_name:
        duplicate = env['x_chair'].search([
            ('x_name', '=ilike', record.x_name.strip()),
            ('id', '!=', record.id)
        ], limit=1)
        if duplicate:
            raise UserError("Conflict: A chair with the name '%s' already exists." % record.x_name)

for record in records:
    if record.x_studio_date:
        bookings = env['x_appointment'].search([
            ('x_studio_date', '=', record.x_studio_date),
            ('x_studio_selection_1', 'not in', ['Cancelled'])
        ])
        if bookings:
            raise UserError("Cannot mark %s as a holiday because there are already %d booking(s) scheduled on this day." % (record.x_studio_date.strftime('%Y-%m-%d'), len(bookings)))

for record in records:
    # 1. Weekly Holiday Conflict Check
    checked_days = []
    if record.x_studio_holiday_monday: checked_days.append(0)
    if record.x_studio_holiday_tuesday: checked_days.append(1)
    if record.x_studio_holiday_wednesday: checked_days.append(2)
    if record.x_studio_holiday_thursday: checked_days.append(3)
    if record.x_studio_holiday_friday: checked_days.append(4)
    if record.x_studio_holiday_saturday: checked_days.append(5)
    if record.x_studio_holiday_sunday: checked_days.append(6)

    if checked_days:
        today = datetime.date.today()
        active_appointments = env['x_appointment'].search([
            ('x_studio_selection_1', 'not in', ['Cancelled']),
            ('x_studio_date', '>=', today)
        ])
        for appt in active_appointments:
            if appt.x_studio_date and appt.x_studio_date.weekday() in checked_days:
                day_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
                raise UserError("Cannot set %s as a weekly holiday because there is already a booking scheduled on that day (%s)." % (day_names[appt.x_studio_date.weekday()], appt.x_studio_date.strftime('%Y-%m-%d')))

for record in records:
    # Reset settings fields if disabled
    if not record.x_studio_allow_break:
        record.write({
            'x_studio_break_start': False,
            'x_studio_break_end': False
        })

    # 1. Break Time Sanity Check
    if record.x_studio_allow_break and record.x_studio_break_start and record.x_studio_break_end:
        b_start_h, b_start_m = map(int, record.x_studio_break_start.split(':'))
        b_end_h, b_end_m = map(int, record.x_studio_break_end.split(':'))
        bs = b_start_h * 60 + b_start_m
        be = b_end_h * 60 + b_end_m
        if be <= bs:
            raise UserError("Break End Time must be strictly later than Break Start Time.")

        # Break Time Confirmed Bookings Overlap Check
        today = datetime.date.today()
        bookings = env['x_appointment'].search([
            ('x_studio_selection_1', '=', 'Confirmed'),
            ('x_studio_date', '>=', today)
        ])
        for appt in bookings:
            if appt.x_studio_time_slot:
                appt_start_h, appt_start_m = map(int, appt.x_studio_time_slot.split(':'))
                as_min = appt_start_h * 60 + appt_start_m
                ae_min = as_min + (appt.x_studio_duration or 30)
                if as_min < be and bs < ae_min:
                    # Format time slots nicely for the error message
                    def format_time_label(val):
                        h, m = map(int, val.split(':'))
                        ampm = 'AM' if h < 12 else 'PM'
                        display_h = h if h <= 12 else h - 12
                        if display_h == 0: display_h = 12
                        return "%02d:%02d %s" % (display_h, m, ampm)

                    b_start_label = format_time_label(record.x_studio_break_start)
                    b_end_label = format_time_label(record.x_studio_break_end)
                    appt_time_label = format_time_label(appt.x_studio_time_slot)

                    raise UserError("Conflict: Cannot save break time %s to %s. There is already a confirmed booking scheduled on %s starting at %s (%d mins). Please adjust the break time or the booking." % (b_start_label, b_end_label, appt.x_studio_date.strftime('%Y-%m-%d'), appt_time_label, appt.x_studio_duration or 30))

target_records = [env.context['onchange_self']] if env.context.get('onchange_self') else (records if records is not None else [record])
for rec in target_records:
    if rec:
        rec.write({
            'x_studio_service': False,
            'x_studio_service_package': False,
            'x_studio_staff_beautician': False,
            'x_studio_value': 0.0,
            'x_studio_duration': 0,
        })

